describe('Async Data Fetching', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should render the initial page without blocking while fetching data', () => {
        cy.intercept('GET', '/api/data', { fixture: 'data.json' }).as('fetchData');

        cy.get('.loading-indicator').should('be.visible'); // Assuming there's a loading indicator

        cy.wait('@fetchData');

        cy.get('.loading-indicator').should('not.exist'); // Loading indicator should disappear
        cy.get('.data-container').should('be.visible'); // Data container should be visible
    });

    it('should handle fetch failure gracefully', () => {
        cy.intercept('GET', '/api/data', { statusCode: 500 }).as('fetchDataError');

        cy.get('.loading-indicator').should('be.visible');

        cy.wait('@fetchDataError');

        cy.get('.loading-indicator').should('not.exist');
        cy.get('.error-message').should('be.visible').and('contain', 'Failed to fetch data'); // Assuming there's an error message
    });
});
